class SparkEngineApplicationsPager:
    """
    SparkEngineApplicationsPager can be used to simplify the use of the "list_spark_engine_applications" method.
    """

    def __init__(
        self,
        *,
        client: WatsonxDataV3,
        id: str,
        auth_instance_id: str = None,
        state: List[str] = None,
        submission_time_interval: str = None,
        start_time_interval: str = None,
        end_time_interval: str = None,
        limit: int = None,
    ) -> None:
        """
        Initialize a SparkEngineApplicationsPager object.
        :param str id: engine id.
        :param str auth_instance_id: (optional) watsonx.data instance ID.
        :param List[str] state: (optional) state.
        :param str submission_time_interval: (optional) Submission time interval in
               <lower timestamp limit>,<upper timestamp limit> format.
        :param str start_time_interval: (optional) Start time interval in <lower
               timestamp limit>,<upper timestamp limit> format.
        :param str end_time_interval: (optional) End time interval in <lower
               timestamp limit>,<upper timestamp limit> format.
        :param int limit: (optional) limit to specify the rows.
        """
        self._has_next = True
        self._client = client
        self._page_context = {'next': None}
        self._id = id
        self._auth_instance_id = auth_instance_id
        self._state = state
        self._submission_time_interval = submission_time_interval
        self._start_time_interval = start_time_interval
        self._end_time_interval = end_time_interval
        self._limit = limit

    def has_next(self) -> bool:
        """
        Returns true if there are potentially more results to be retrieved.
        """
        return self._has_next

    def get_next(self) -> List[dict]:
        """
        Returns the next page of results.
        :return: A List[dict], where each element is a dict that represents an instance of SparkEngineApplicationSummary.
        :rtype: List[dict]
        """
        if not self.has_next():
            raise StopIteration(message='No more results available')

        result = self._client.list_spark_engine_applications(
            id=self._id,
            auth_instance_id=self._auth_instance_id,
            state=self._state,
            submission_time_interval=self._submission_time_interval,
            start_time_interval=self._start_time_interval,
            end_time_interval=self._end_time_interval,
            limit=self._limit,
            start=self._page_context.get('next'),
        ).get_result()

        next = None
        next_page_link = result.get('next')
        if next_page_link is not None:
            next = get_query_param(next_page_link.get('href'), 'start')
        self._page_context['next'] = next
        if next is None:
            self._has_next = False

        return result.get('applications')

    def get_all(self) -> List[dict]:
        """
        Returns all results by invoking get_next() repeatedly
        until all pages of results have been retrieved.
        :return: A List[dict], where each element is a dict that represents an instance of SparkEngineApplicationSummary.
        :rtype: List[dict]
        """
        results = []
        while self.has_next():
            next_page = self.get_next()
            results.extend(next_page)
        return results


